const origin=window.location.origin;
const h={'Tj-Workspace-Id':constants.WS};
const CR=constants.CHANGE_REQUESTS_TABLE;
try{
  const r=await fetch(origin+'/api/tooljet-db/proxy/'+CR+'?order=created_at.desc&limit=3&select=id,config_type,domain,status,created_at,payload',{credentials:'include',headers:h});
  const t=await r.text();
  const j=t?JSON.parse(t):[];
  const rows=Array.isArray(j)?j:[];
  const fmt=ts=>{ if(!ts) return ''; const d=new Date(ts); return d.toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}); };
  return rows.map(r=>{
    const p=r.payload||{};
    const status=r.status==='SUBMITTED'?'Awaiting approval':r.status==='APPROVED'?'Approved':r.status==='REJECTED'?'Rejected':r.status==='CANCELLED'?'Cancelled':r.status;
    return { id:r.id, name:(p.rule_name||p.config_name||r.config_type||'Rule')+' \u00b7 '+(r.domain||''), sub:r.config_type||'', status, time: fmt(r.created_at) };
  });
}catch(e){ console.warn('getRecentActivity failed', e.message); return []; }
